def page(self) -> Page:
    # Tabs can close themselves; fall back to the tab that opened them.
    while len(self._pages) > 1 and self._pages[-1].is_closed():
        self._pages.pop()
        self._notices.append("The newest tab closed; you are back on the tab before it.")
    return self._pages[-1]

