"""Replaces identifiers from the websites by stable aliases (same identifier, same alias) and masks all other digits,
so the structure of a log can be read without showing its values."""
import re
_seen = {}
def _alias(kind, token):
    key = (kind, token)
    if key not in _seen:
        _seen[key] = f"{kind}{sum(1 for k in _seen if k[0] == kind) + 1}"
    return _seen[key]
def alias(text):
    text = re.sub(r"\b([A-Z]{1,4})-(\d[\d-]*)\b", lambda m: "<" + _alias(m.group(1), m.group(0)) + ">", text)
    text = re.sub(r"\b\d\d\.\d\d\b(?!\.\d)", lambda m: "<" + _alias("POS", m.group(0)) + ">", text)
    return re.sub(r"\d", "#", text)
